async function main() { const startTime = Date.now(); const allResults = []; const tierRunners = [ { tier: 1, name: 'TIER 1: FEATURE COVERAGE', runner: runTier1Tests }, { tier: 2, name: 'TIER 2: BOUNDARY & CORNER CASES', runner: runTier2Tests }, { tier: 3, name: 'TIER 3: CROSS-FEATURE COMBINATIONS', runner: runTier3Tests }, { tier: 4, name: 'TIER 4: REAL-WORLD ACCEPTANCE SCENARIOS', runner: runTier4Tests }, ]; if (!isJson) { console.log(`${BOLD}${CYAN}================================================================================${RESET}`); console.log(`${BOLD}${CYAN} TRUSTIO UX AUDIT — OPAQUE-BOX E2E VERIFICATION SUITE${RESET}`); console.log(`${GRAY} Execution Timestamp: ${new Date().toISOString()}${RESET}`); console.log(`${GRAY} Target Audit Dir: ${auditDir}${RESET}`); console.log(`${GRAY} Execution Mode: ${isStrict ? 'STRICT (Pending = Fail)' : 'PROGRESSIVE (Pending Allowed for In-Flight Milestones)'}${RESET}`); if (targetTier) { console.log(`${GRAY} Filtered to Tier: ${targetTier}${RESET}`); } console.log(`${BOLD}${CYAN}================================================================================${RESET}
`); } for (const { tier, name, runner } of tierRunners) { if (targetTier && targetTier !== tier) continue; if (!isJson) { console.log(`${BOLD}─── ${name} ──────────────────────────────────────────────────${RESET}`); } try { const tierResults = await runner(context); allResults.push(...tierResults); if (!isJson) { for (const res of tierResults) { let badge; if (res.status === 'PASS') { badge = `${GREEN}[ PASS ]${RESET}`; } else if (res.status === 'PENDING') { badge = `${YELLOW}[ PEND ]${RESET}`; } else { badge = `${RED}[ FAIL ]${RESET}`; } console.log(` ${badge} ${BOLD}${res.id}${RESET} - ${res.name} ${GRAY}(${res.durationMs}ms)${RESET}`); if (res.details) { console.log(` ${GRAY}↳ ${res.details}${RESET}`); } if (res.error && res.status === 'FAIL') { console.log(` ${RED}↳ Error: ${res.error.message}${RESET}`); } if (isVerbose && res.meta) { console.log(` ${GRAY}↳ Meta: ${JSON.stringify(res.meta)}${RESET}`); } } console.log(''); } } catch (err) { const failedResult = { tier, id: `T${tier}.X`, name: `Suite Execution for Tier ${tier}`, status: 'FAIL', durationMs: 0, details: `Unhandled runner crash: ${err.message}`, error: err, }; allResults.push(failedResult); if (!isJson) { console.log(` ${RED}[ CRASH ]${RESET} Unhandled error running Tier ${tier}: ${err.message}
`); } } } const durationMs = Date.now() - startTime; const passed = allResults.filter((r) => r.status === 'PASS').length; const pending = allResults.filter((r) => r.status === 'PENDING').length; const failed = allResults.filter((r) => r.status === 'FAIL').length; const total = allResults.length; const summary = { total, passed, pending, failed, durationMs, allPassed: failed === 0 && (!isStrict || pending === 0), }; if (isJson) { console.log( JSON.stringify( { timestamp: new Date().toISOString(), auditDir, isStrict, summary, results: allResults, }, null, 2 ) ); } else { console.log(`${BOLD}────────────────────────────────────────────────────────────────────────────────${RESET}`); console.log(`${BOLD} E2E TEST SUITE SUMMARY${RESET}`); console.log(`${BOLD}────────────────────────────────────────────────────────────────────────────────${RESET}`); console.log(` Total Assertions: ${total}`); console.log(` ${GREEN}Passed:${RESET} ${passed}`); console.log(` ${YELLOW}Pending:${RESET} ${pending} ${pending > 0 ? '(Awaiting M1/M3 deliverable completion)' : ''}`); console.log(` ${failed > 0 ? RED : GRAY}Failed:${RESET} ${failed}`); console.log(` Duration: ${durationMs}ms`); let verdictColor = GREEN; let verdictText = 'PASSED (100% SATISFIED)'; if (failed > 0) { verdictColor = RED; verdictText = 'FAILED (Defects Detected)'; } else if (pending > 0) { verdictColor = YELLOW; verdictText = isStrict ? 'FAILED (Strict Mode: Unresolved Pending)' : 'IN PROGRESS (Deliverables Pending Downstream Workers)'; } console.log(` Verdict: ${BOLD}${verdictColor}${verdictText}${RESET}`); console.log(`${BOLD}${CYAN}================================================================================${RESET}
`); } // Determine exit code if (failed > 0) { process.exit(1); } if (isStrict && pending > 0) { process.exit(1); } process.exit(0); }

/* assets/chat.js — área do cliente (/app/). Sessão via Supabase Auth; mensagens via função "chat" (streaming SSE). Nenhuma chave secreta aqui: a chave do modelo fica no servidor. */ (function () { "use strict"; // Mesmo arquivo nas duas versões do site: o texto segue o idioma da página. var EN = /^en /i.test(document.documentElement.lang); var LOCAL = EN ? "en-US" : "pt-BR"; var CFG = window.TRUSTIO_AUTH; if (!CFG || !window.supabase) return; var sb = window.supabase.createClient(CFG.url, CFG.key, { auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true } }); var shell = $(".chat-shell"); var thread = $("[data-thread]"); var welcome = $("[data-welcome]"); var composer = $("[data-composer]"); var input = $("#prompt"); var sendBtn = $("[data-send]"); var notice = $("[data-notice]"); var paywall = $("[data-paywall]"); var convList = $("[data-conversations]"); var convEmpty = $("[data-conv-empty]"); var convTitle = $("[data-conv-title]"); var deleteBtn = $("[data-delete]"); var gate = $("[data-gate]"); var state = { user: null, lead: null, limit: 0, conversationId: null, conversations: [], sending: false, threadInner: null, isAdmin: false, fechado: false, sessaoCheia: false, placeholderPadrao: "", escolhas: 0 }; // ---------------------------------------------------------------- utilidades // Sem cota de perguntas: assinante, ou tipo de usuário admin, colaborador ou cliente // (a mesma regra do reserve_chat_message no banco). // Renderização mínima e segura de Markdown (blocos de código, inline, negrito, listas, títulos). // ---------------------------------------------------------------- sessão var recoveryMode = /[?&]recovery=1/.test(location.search) || /type=recovery/.test(location.hash); sb.auth.onAuthStateChange(function (event, session) { if (event === "PASSWORD_RECOVERY") { recoveryMode = true; showRecovery(); } if (event === "SIGNED_OUT") { location.replace(CFG.loginPath); } }); // Pergunta à função se esta conta já pode conversar. Nenhum segredo volta daqui. // "1º de outubro", "23 de setembro" — a mesma forma que o resto do site usa. // Estado, não um disable pontual: enquanto state.fechado for verdadeiro nada envia, // nem pelo formulário, nem pelo Enter, nem pelos botões de sugestão. // ---------------------------------------------------------------- widgets de boas-vindas var waForm = $("[data-wa-form]"); if (waForm) waForm.addEventListener("submit", function (e) { e.preventDefault(); var btn = $("[data-wa-submit]"), st = $("[data-wa-status]"), num = $("#wa-num").value; if (num.replace(/\D/g, "").length < 10) { st.hidden = false; st.className = "is-error"; st.textContent = T("Digite o número com DDD.", "Enter the number with the area code."); return; } btn.disabled = true; btn.textContent = T("Enviando…", "Sending…"); sb.rpc("request_whatsapp_trial", { p_numero: num }).then(function (r) { if (r.error) throw r.error; var d = r.data || {}; if (!d.ok) throw new Error(d.error || "erro"); if (state.lead) { state.lead.whatsapp_trial_status = d.status; state.lead.whatsapp_numero = d.numero; state.lead.whatsapp_trial_requested_at = d.requested_at; state.lead.whatsapp_trial_started_at = d.started_at; state.lead.whatsapp_trial_ends_at = d.ends_at; } renderWhatsapp(); }).catch(function (err) { btn.disabled = false; btn.textContent = T("Quero os 3 dias", "I want the 3 days"); st.hidden = false; st.className = "is-error"; st.textContent = String(err.message || "").indexOf("numero_invalido") >= 0 ? T("Número inválido. Use DDD + número.", "Invalid number. Use area code + number.") : T("Não foi possível registrar agora. Tente de novo.", "We couldn't register that right now. Try again."); }); }); var obStart = $("[data-ob-start]"); if (obStart) obStart.addEventListener("click", function () { welcome.dataset.mode = "returning"; if (state.lead && !state.lead.onboarding_seen_at) { state.lead.onboarding_seen_at = new Date().toISOString(); sb.rpc("mark_onboarding_seen").then(function () {}); } input.focus(); }); var obOpen = $("[data-ob-open]"); if (obOpen) obOpen.addEventListener("click", function () { if (state.sending) return; resetThread(); renderOnboard(true); thread.scrollTop = 0; closeSide(); }); // ---------------------------------------------------------------- conversas // Sessão da aba: ao recarregar, a conversa continua se começou há menos de 2 horas; // depois disso, a aba começa uma sessão nova. Uma aba nova sempre começa do zero // (sessionStorage não passa de uma aba para outra). var CHAVE_SESSAO = "trustio-conversa-da-aba", JANELA_SESSAO_MS = 2 * 60 * 60 * 1000; // Trocar de conversa (ou começar outra) sai da sessão que encheu o contexto. // Mensagem do usuário: texto como veio, e cada anexo (texto extraído por OCR) recolhido. var RE_ANEXO = /
*\[\[anexo: ([^\]
]*)\]\]
([\s\S]*?)
\[\[/anexo\]\]/g; // A conversa encheu o contexto do modelo: não dá para continuar nela. Uma aba nova // começa uma conversa nova (sem conversation_id), com o contexto vazio. // ---------------------------------------------------------------- envio // ---------------------------------------------------------------- anexos (fotos e PDFs, OCR no navegador) // Até 3 arquivos por envio. O arquivo não sai do aparelho: assets/ocr.js extrai o texto // aqui, e o texto vai junto da mensagem, em blocos [[anexo: …]] … [[/anexo]]; das fotos vai // também uma cópia reduzida, para o modelo ver o que não é texto. // LIMITE_MENSAGEM acompanha o teto da função chat (40 mil), com folga para os marcadores. var MAX_ANEXOS = 3, MAX_BYTES = 10 * 1024 * 1024, MAX_TEXTO_ANEXO = 12000, MAX_TEXTO_TOTAL = 30000, LIMITE_MENSAGEM = 39000; // "[[anexo" digitado ou dentro de um documento não pode abrir nem fechar um bloco de anexo: // um espaço invisível entre os colchetes desfaz o marcador sem mudar o que se lê. var anexos = [], seqAnexo = 0; var anexosEl = $("[data-anexos]"), fileInput = $("[data-file]"), attachBtn = $("[data-attach]"); // Blocos que vão para o modelo, com teto por anexo e no total (o contexto do modelo é finito). attachBtn.addEventListener("click", function () { if (!attachBtn.disabled) fileInput.click(); }); fileInput.addEventListener("change", function () { adicionarArquivos(fileInput.files); fileInput.value = ""; }); anexosEl.addEventListener("click", function (e) { var b = e.target.closest("[data-anexo-remove]"); if (!b) return; var id = Number(b.closest("[data-anexo-id]").dataset.anexoId); anexos = anexos.filter(function (a) { return a.id !== id; }); renderAnexos(); input.focus(); }); // Colar uma imagem (print) e arrastar arquivos para a conversa também anexam. input.addEventListener("paste", function (e) { var cd = e.clipboardData; if (!cd || !cd.files || !cd.files.length) return; var aceitos = Array.prototype.filter.call(cd.files, tipoAceito); if (!aceitos.length) return; // nada anexável: a colagem segue normal // Com texto junto (ex.: trecho de página com imagem), o texto entra na caixa normalmente. if (!cd.getData("text/plain")) e.preventDefault(); adicionarArquivos(aceitos); }); ["dragover", "drop"].forEach(function (ev) { composer.addEventListener(ev, function (e) { if (!e.dataTransfer || Array.prototype.indexOf.call(e.dataTransfer.types || [], "Files") < 0) return; e.preventDefault(); if (ev === "drop") adicionarArquivos(e.dataTransfer.files); }); }); // ---------------------------------------------------------------- UI composer.addEventListener("submit", function (e) { e.preventDefault(); send(input.value); }); input.addEventListener("keydown", function (e) { if (e.key === "Enter" && !e.shiftKey && !e.isComposing) { e.preventDefault(); send(input.value); } }); input.addEventListener("input", autosize); document.querySelectorAll("[data-starter]").forEach(function (b) { b.addEventListener("click", function () { input.value = b.textContent; autosize(); send(input.value); }); }); $("[data-new]").addEventListener("click", function () { if (!state.sending) { resetThread(); input.focus(); closeSide(); } }); deleteBtn.addEventListener("click", function () { if (!state.conversationId || state.sending) return; if (!confirm(T("Apagar esta conversa? Isso não pode ser desfeito.", "Delete this conversation? This can't be undone."))) return; var id = state.conversationId; sb.from("conversations").delete().eq("id", id).then(function () { state.conversations = state.conversations.filter(function (c) { return c.id !== id; }); resetThread(); }); }); $("[data-logout]").addEventListener("click", function () { sb.auth.signOut(); }); document.addEventListener("click", function (e) { var t = e.target.closest("[data-resend-confirm]"); if (!t) return; t.disabled = true; sb.auth.resend({ type: "signup", email: state.user.email, options: { emailRedirectTo: location.origin + CFG.appPath } }) .then(function () { showNotice(T("Novo link enviado para ", "New link sent to ") + esc(state.user.email) + "."); }); }); $("[data-side-open]").addEventListener("click", openSide); $("[data-side-close]").addEventListener("click", closeSide); document.addEventListener("keydown", function (e) { if (e.key === "Escape") closeSide(); }); // Tema (mesma chave do site). var toggle = $(".theme-toggle"); toggle.addEventListener("click", function () { applyTheme(document.documentElement.getAttribute("data-theme") === "light" ? "dark" : "light"); }); toggle.setAttribute("aria-pressed", document.documentElement.getAttribute("data-theme") === "light" ? "true" : "false"); boot(); })();

function pump() { return reader.read().then(function (step) { if (step.done) return; buf += dec.decode(step.value, { stream: true }); var events = buf.split("

"); buf = events.pop(); events.forEach(function (ev) { var line = ev.split("
").filter(function (l) { return l.indexOf("data:") === 0; })[0]; if (!line) return; var d; try { d = JSON.parse(line.slice(5)); } catch (e) { return; } if (d.conversation_id && !state.conversationId) { state.conversationId = d.conversation_id; lembrarConversa(d.conversation_id); } if (d.limite) { limite = Number(d.limite) || 0; prog.classList.remove("is-open"); mostrarProgresso(); } if (d.raciocinio) { contar(d); // Tokens só do raciocínio ("nr", da função); sem ele, o total até a resposta começar. tokensPensando = typeof d.nr === "number" ? d.nr : (full ? tokensPensando : tokens); if (think.hidden) think.hidden = false; var noFim = thinkText.scrollTop + thinkText.clientHeight >= thinkText.scrollHeight - 8; thinkText.textContent += d.raciocinio; if (noFim) thinkText.scrollTop = thinkText.scrollHeight; mostrarProgresso(); scrollBottom(); } if (d.delta) { // Primeiro trecho da resposta: o raciocínio recolhe e a resposta fica em foco. if (!full && !think.hidden) think.open = false; contar(d); full += d.delta; body.innerHTML = render(full); mostrarProgresso(); scrollBottom(); } if (!d.delta && !d.raciocinio && typeof d.n === "number" && !d.done) { contar(d); mostrarProgresso(); } if (d.error) { avisado = true; if (d.error === "stream_interrompido") interrompida = true; if (!full) body.textContent = ""; showNotice(d.error === "resposta_vazia" ? T("O modelo não devolveu resposta desta vez, e a mensagem não foi descontada. Tente enviar de novo.", "The model didn't return an answer this time, and the message wasn't counted. Try sending again.") : T("A resposta foi interrompida. Tente enviar de novo.", "The answer was cut off. Try sending again.")); } if (d.done) { if (typeof d.n === "number") contar(d); if (typeof d.nr === "number" && !think.hidden) { tokensPensando = d.nr; thinkSum.textContent = T("Raciocínio", "Reasoning") + " · " + tokensPensando + " tokens"; } var seg = ((Date.now() - inicio) / 1000).toFixed(1); progFill.style.width = "100%"; prog.setAttribute("aria-valuenow", "100"); prog.classList.add("is-done"); progTxt.textContent = (interrompida ? T("Interrompida", "Interrupted") : d.fim === "length" ? T("Resposta cortada no limite", "Answer cut off at the limit") : T("Concluída", "Done")) + " · " + tokens + " tokens · " + (EN ? seg : seg.replace(".", ",")) + " s" + (d.contexto && d.janela ? T(" · sessão ", " · session ") + Math.min(100, Math.round(d.contexto / d.janela * 100)) + "%" : ""); // Sessão cheia é o contexto do modelo quase todo usado (a próxima mensagem não // caberia), não a resposta ter batido no teto de tokens por resposta. if (d.contexto && d.janela && d.contexto >= d.janela * 0.95) sessaoCheia(d.janela); afterDone(d); } }); return pump(); }); }

function blocosDeAnexo(lista, orcamento) { // Orçamento = o que sobra do limite da mensagem depois do texto digitado; os marcadores // e nomes também contam (reserva de 200 por anexo). var out = "", usado = 0, teto_total = Math.min(MAX_TEXTO_TOTAL, Math.max(0, (orcamento || MAX_TEXTO_TOTAL) - 200 * lista.length)); lista.forEach(function (a) { var livre = teto_total - usado; if (livre <= 200) return; // Foto sem texto: o bloco registra no histórico que houve uma foto (a imagem vai à parte). var teto = Math.min(MAX_TEXTO_ANEXO, livre), txt = semMarcador(a.texto) || T("(foto sem texto legível; a imagem só vai ao modelo na mensagem em que foi anexada)", "(photo with no readable text; the image only goes to the model in the message it was attached to)"), cortado = txt.length > teto; if (cortado) txt = txt.slice(0, teto); usado += txt.length; var pags = a.pdf && a.info ? a.info.paginas : 0; var titulo = a.nome.replace(/[\[\]
]/g, " ") + (a.pdf ? "" : T(" · foto", " · photo")) + (pags ? " · " + pags + (pags === 1 ? T(" página", " page") : T(" páginas", " pages")) : "") + (cortado ? T(" · texto cortado", " · text truncated") : ""); out += "

[[anexo: " + titulo + "]]
" + txt + "
[[/anexo]]"; }); return out; }

#!/usr/bin/env node // Gera a versão em inglês do site (en/) a partir das páginas em português. // // O português continua sendo a fonte: cada página em en/ é a página em português // com o texto trocado pelo dicionário em i18n/en/, os caminhos ajustados para um // nível abaixo e o idioma declarado. Assim uma correção de layout feita no // português chega ao inglês na próxima geração, sem ninguém copiar HTML à mão. // // Também escreve, nas duas versões, a bandeira de troca de idioma no cabeçalho e // os <link rel="alternate" hreflang> — entre marcadores, então rodar de novo não // duplica nada. // // npm run i18n gera en/ e atualiza bandeira e hreflang no português // npm run i18n:check falha se en/ estiver desatualizado ou se sobrar // texto sem tradução (use no CI, como o stamp:check) // npm run i18n -- --faltando lista o que ainda não tem tradução import { readFile, writeFile, mkdir } from "node:fs/promises"; import { existsSync } from "node:fs"; import { dirname, join } from "node:path"; import { fileURLToPath } from "node:url"; const ROOT = join(dirname(fileURLToPath(import.meta.url)), ".."); const SITE = "https://trustio.com.br"; const args = new Set(process.argv.slice(2)); const CHECK = args.has("--check"); const LISTAR = args.has("--faltando"); // Páginas espelhadas em en/. Ficam só em português, de propósito: admin/ e crm/ // (ferramentas internas do operador), planos-teste.html (noindex, checkout de // teste) e voice-mvp/ (outra aplicação, publicada à parte). export const PAGINAS = [ "index.html", "modelos.html", "voice.html", "agentio.html", "planos.html", "espera.html", "manifesto.html", "fundador.html", "privacidade.html", "seats.html", "cadastro.html", "entrar.html", "obrigado.html", "404.html", "juridico/index.html", "app/index.html", "console/index.html", ]; const ESPELHADAS = new Set(PAGINAS); // Onde a bandeira entra quando a página não tem o botão de tema. const ANCORA_BANDEIRA = { "404.html": '<div class="error-content">', "console/index.html": '<a class="btn btn-ghost" href="../voice.html">', }; // Texto que não se traduz: marcas, siglas, nomes próprios. const MARCAS = new Set([ "Trustio", "Trust", "io", "VoiceAI", "Omnichannel", "Pix", "Stripe", "xSpace", "WhatsApp", "Telegram", "LGPD", "ANPD", "ISO 27001", "Hermes", "OpenAI", "Supabase", "Cloudflare", "Resend", "Apple Pay", "Google Pay", "RAG", "OCR", "API", "SSO", "SIEM", "VPC", "GPU", "SLA", "CRM", "CSV", "PDF", "Starter", "Pro", "Dedicado", "Crédito Jus", "br-sao-1", "Gmail", "Outlook", "powered by xSpace", "Agentio", "Agentio · Nous", "Nous Research", "Hermes Agent", "by", "Agent Builder", "SAFE ROUTE", "TRUSTIO / SAFE ROUTE", // a própria bandeira: é reescrita depois da tradução "EN", "PT", "English", "Português", "Switch to English", "Mudar para português", ]); // ─────────────────────────────────────────────────────────────── entidades const ENTIDADES = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ", atilde: "ã", Atilde: "Ã", otilde: "õ", Otilde: "Õ", eacute: "é", Eacute: "É", aacute: "á", Aacute: "Á", iacute: "í", Iacute: "Í", oacute: "ó", Oacute: "Ó", uacute: "ú", Uacute: "Ú", ecirc: "ê", Ecirc: "Ê", acirc: "â", Acirc: "Â", ocirc: "ô", Ocirc: "Ô", ccedil: "ç", Ccedil: "Ç", agrave: "à", Agrave: "À", middot: "·", mdash: "—", ndash: "–", hellip: "…", ordm: "º", ordf: "ª", ldquo: "“", rdquo: "”", lsquo: "‘", rsquo: "’", harr: "↔", rarr: "→", larr: "←", darr: "↓", uarr: "↑", check: "✓", times: "×", copy: "©", reg: "®", trade: "™", deg: "°", euro: "€", bull: "•", }; // Não precisa de tradução: sem letras, e-mail, endereço, marca. // ─────────────────────────────────────────────────────────────── dicionários // ─────────────────────────────────────────────────────────────── endereços // Um nível abaixo, em en/: link para página espelhada continua relativo (a árvore // é a mesma); todo o resto vira absoluto a partir da raiz, então asset e página // que só existe em português continuam funcionando de qualquer profundidade. // ─────────────────────────────────────────────────────────────── bandeira e hreflang const BANDEIRA_BR = '<svg viewBox="0 0 20 14" aria-hidden="true" focusable="false"><rect width="20" height="14" fill="#009c3b"/><path d="M10 1.6 18.4 7 10 12.4 1.6 7z" fill="#ffdf00"/><circle cx="10" cy="7" r="3.1" fill="#002776"/></svg>'; const BANDEIRA_US = '<svg viewBox="0 0 20 14" aria-hidden="true" focusable="false"><rect width="20" height="14" fill="#b22234"/><path d="M0 1.62h20M0 3.77h20M0 5.92h20M0 8.08h20M0 10.23h20M0 12.38h20" stroke="#fff" stroke-width="1.08"/><rect width="8.6" height="7.54" fill="#3c3b6e"/></svg>'; // ─────────────────────────────────────────────────────────────── tradução const TOKEN = /(<!--[\s\S]*?-->|<script [\s\S]*?</script>|<style [\s\S]*?</style>|<[^>]+>)/gi; const ATRIBUTOS_DE_TEXTO = ["alt", "title", "aria-label", "placeholder"]; const META_DE_TEXTO = /^(description|keywords|og:title|og:description|og:image:alt|twitter:title|twitter:description)$/; // Dados estruturados: mesmo dicionário, só em valores que casam por inteiro. Texto sem // tradução conta como faltando, como no resto da página; identificadores e endereços // (as chaves abaixo) passam direto. const JSONLD_LITERAL = new Set(["@context", "@type", "@id", "url", "logo", "image", "sameAs", "email", "telephone", "addressCountry", "addressRegion", "addressLocality", "postalCode", "priceCurrency", "price", "inLanguage", "contentUrl", "unitCode", "areaServed"]); // ─────────────────────────────────────────────────────────────── execução const comum = await lerDicionario("_comum.json"); let desatualizados = 0, totalFaltando = 0; for (const pagina of PAGINAS) { const caminhoPt = join(ROOT, pagina); const fontePt = await readFile(caminhoPt, "utf8"); // Português: só bandeira e hreflang, entre marcadores. const pt = marcarIdioma(fontePt, pagina, "pt"); if (pt !== fontePt) { if (CHECK) { console.error(`desatualizado: ${pagina} (bandeira/hreflang)`); desatualizados++; } else await writeFile(caminhoPt, pt); } /